import React from 'react';
import Header from './Header';
import './UserPage.css';
import Footer from './Footer';
import user from './User.jpg'

//username, password, email, phone, address, past orders

function User() {
    return(
        <div className='UserPage'>
            <Header/>
            <h1>User Info</h1>
            <table className='Table'>
                    <tr width='100%'></tr>
                    <td className='column1User' width='20%'>
                        <div className='Image'>
                            <img src={user} />
                        </div>
                    </td>  
                    <td className='column2User' width='80%'>  
                        <div className='About'>
                            <p>Nithya.P</p>
                            <p>123@gmail.com</p>
                            <p>123456</p>
                        </div>
                    </td>  
            </table>
            <hr classname="hr"/>
            <div className='PastHistory'>
                <h3>Past Orders</h3>
                <div></div>
            </div>
            <Footer/>
        </div>
    );
}


export default User;
